-- OFFLINE synthetic PG17 ONLY. No old role/function/ACL is changed.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_managed_normalized') IS NULL OR to_regnamespace('design_normalization_processing') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_normalization_runtime LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_normalization_processing_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_normalization_runtime,design_normalization_processing_issuer;
CREATE SCHEMA design_normalization_processing AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_normalization_processing FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_normalization_processing TO design_normalization_runtime,design_normalization_processing_issuer,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_normalization_processing TO design_managed_image_capability;
CREATE TABLE design_normalization_processing.permissions(id text PRIMARY KEY,owner_key text NOT NULL,request_id text NOT NULL,authority jsonb NOT NULL,intent jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(owner_key,request_id));
CREATE TABLE design_normalization_processing.claims(id text PRIMARY KEY,owner_key text NOT NULL,request_id text NOT NULL,permission_id text NOT NULL REFERENCES design_normalization_processing.permissions,intent jsonb NOT NULL,UNIQUE(owner_key,request_id));
CREATE TABLE design_normalization_processing.artifact_bindings(claim_id text PRIMARY KEY REFERENCES design_normalization_processing.claims,artifact_digest text NOT NULL UNIQUE,artifact jsonb NOT NULL);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['permissions','claims','artifact_bindings'] LOOP EXECUTE format('ALTER TABLE design_normalization_processing.%I OWNER TO design_identity_owner',t);EXECUTE format('ALTER TABLE design_normalization_processing.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_normalization_processing.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY capability_only ON design_normalization_processing.%I TO design_managed_image_capability USING(true) WITH CHECK(true)',t);EXECUTE format('GRANT SELECT,INSERT ON design_normalization_processing.%I TO design_managed_image_capability',t);EXECUTE format('CREATE TRIGGER processing_immutable BEFORE UPDATE OR DELETE ON design_normalization_processing.%I FOR EACH ROW EXECUTE FUNCTION design_managed_image.immutable_row()',t);END LOOP;END$$;
GRANT UPDATE(active) ON design_normalization_processing.permissions TO design_managed_image_capability;
CREATE FUNCTION design_normalization_processing.resolve(token text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN
 IF (session_user NOT IN ('design_normalization_runtime','design_normalization_processing_issuer') OR token IS NULL OR length(token) NOT BETWEEN 32 AND 200 OR token~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(token,'UTF8')),'hex'),scope);
 IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;RETURN r->'authority';END$$;
-- Stable request namespace deliberately excludes changing epochs and display names.
CREATE FUNCTION design_normalization_processing.owner_key(a jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT design_dependency_authority.digest(jsonb_build_array(a->'subjectId',a->'employmentId',a->'membershipId',a->'storeId'))$$;
CREATE FUNCTION design_normalization_processing.policy() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT '{"id":"managed-imgproxy-png-normalization","version":"1","runtime":{"id":"supabase-imgproxy","version":"3.8.0","imageDigest":"sha256:0facd355d50f3be665ebe674486f2b2e9cdaebd3f74404acd9b7fece2f661435"},"inputMimeTypes":["image/jpeg","image/webp"],"outputMime":"image/png","resize":"none","parentOrientation":"absent_or_identity","color":"srgb","pixelEquality":"exact_srgb","metadata":"strip_all","maximumFrames":1,"containerNormalization":"remove_pHYs_only","outputPixelFormat":"rgb8_noninterlaced"}'::jsonb$$;
CREATE FUNCTION design_normalization_processing.parent_context(a jsonb,media text,parent_request text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s jsonb;r jsonb;o jsonb;rd text;BEGIN
 IF (media IS NULL OR media!~'^[A-Za-z0-9_-]{1,100}$' OR parent_request IS NULL OR parent_request!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_INVALID' USING ERRCODE='42501';END IF;
 SELECT src.record INTO STRICT s FROM design_managed_image.sources src WHERE src.owner_key=design_managed_image.owner_key(a) AND src.media_id=media AND src.active FOR SHARE;
 SELECT res.record INTO STRICT r FROM design_managed_image.responses res WHERE res.source_digest=design_dependency_authority.digest(s) AND res.request_id=parent_request;
 rd:=design_managed_derived.check_response(a,r);SELECT obj.receipt INTO STRICT o FROM design_managed_derived.objects obj WHERE obj.response_digest=rd;PERFORM design_managed_derived.check_object(a,rd,o);
 IF (s->'owner' IS DISTINCT FROM a OR r->>'sourceRecordDigest' IS DISTINCT FROM design_dependency_authority.digest(s) OR o->'derivative'->>'mime' NOT IN ('image/jpeg','image/webp')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_PARENT_DENIED' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('sourceRecord',s,'parentResponse',r,'parentObjectReceipt',o);END$$;
CREATE FUNCTION design_normalization_processing.make_intent(a jsonb,p jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF (rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_INVALID' USING ERRCODE='42501';END IF;
 RETURN p||jsonb_build_object('schemaVersion','design-normalization-processing-intent-v1','purpose','private_parent_png_normalization','requestId',rid,'authority',a,'normalizationPolicy',design_normalization_processing.policy(),'maximumAttempts',1);END$$;
CREATE FUNCTION design_normalization_processing.check_intent(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p jsonb;BEGIN
 IF (NOT design_managed_image.exact(i,ARRAY['schemaVersion','purpose','requestId','authority','sourceRecord','parentResponse','parentObjectReceipt','normalizationPolicy','maximumAttempts']) OR jsonb_typeof(i->'requestId') IS DISTINCT FROM 'string') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_INVALID' USING ERRCODE='42501';END IF;
 p:=design_normalization_processing.parent_context(a,i->'sourceRecord'->>'mediaId',i->'parentResponse'->'descriptor'->>'requestId');
 IF (i IS DISTINCT FROM design_normalization_processing.make_intent(a,p,i->>'requestId')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_BINDING' USING ERRCODE='42501';END IF;RETURN design_dependency_authority.digest(i);END$$;
CREATE FUNCTION design_normalization_processing.permission(a jsonb,i jsonb) RETURNS design_normalization_processing.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_normalization_processing.permissions;BEGIN
 PERFORM design_normalization_processing.check_intent(a,i);SELECT * INTO STRICT p FROM design_normalization_processing.permissions x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId' FOR SHARE;
 IF (NOT p.active OR p.authority IS DISTINCT FROM a OR p.intent IS DISTINCT FROM i OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_normalization_processing.check_claim(a jsonb,i jsonb) RETURNS design_normalization_processing.claims LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_normalization_processing.permissions;c design_normalization_processing.claims;BEGIN
 p:=design_normalization_processing.permission(a,i);SELECT * INTO STRICT c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId';
 IF (c.intent IS DISTINCT FROM i OR c.permission_id IS DISTINCT FROM p.id OR c.id IS DISTINCT FROM 'normalization-claim-'||design_dependency_authority.digest(i) OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;RETURN c;END$$;
CREATE FUNCTION design_normalization_processing.prepare(token text,scope jsonb,media text,parent_request text,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;i jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_normalization_processing.resolve(token,scope);i:=design_normalization_processing.make_intent(a,design_normalization_processing.parent_context(a,media,parent_request),rid);PERFORM design_normalization_processing.check_intent(design_normalization_processing.resolve(token,scope),i);RETURN i;END$$;
CREATE FUNCTION design_normalization_processing.authorize(token text,scope jsonb,i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM design_normalization_processing.permission(design_normalization_processing.resolve(token,scope),i);PERFORM design_normalization_processing.permission(design_normalization_processing.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_normalization_processing.guard(token text,scope jsonb,i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM design_normalization_processing.check_claim(design_normalization_processing.resolve(token,scope),i);PERFORM design_normalization_processing.check_claim(design_normalization_processing.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_normalization_processing.claim(token text,scope jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_normalization_processing.permissions;c design_normalization_processing.claims;result text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_normalization_processing.resolve(token,scope);p:=design_normalization_processing.permission(a,i);
 SELECT * INTO c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId';
 IF FOUND THEN PERFORM design_normalization_processing.check_claim(a,i);result:='already_claimed';ELSE INSERT INTO design_normalization_processing.claims VALUES('normalization-claim-'||design_dependency_authority.digest(i),design_normalization_processing.owner_key(a),i->>'requestId',p.id,i);result:='created';END IF;
 PERFORM design_normalization_processing.check_claim(design_normalization_processing.resolve(token,scope),i);RETURN result;END$$;
-- Private fresh helper for independent strict task/report functions owned by the
-- existing NOLOGIN capability role. No runtime or issuer can call it directly.
CREATE FUNCTION design_normalization_processing.check_bound(a jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c design_normalization_processing.claims;b design_normalization_processing.artifact_bindings;ad text;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));
 SELECT * INTO STRICT c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=rid;PERFORM design_normalization_processing.check_claim(a,c.intent);
 SELECT * INTO STRICT b FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;ad:=design_managed_normalized.check_artifact(a,b.artifact);
 IF (ad IS DISTINCT FROM b.artifact_digest OR b.artifact->>'requestId' IS DISTINCT FROM rid OR c.intent IS DISTINCT FROM design_normalization_processing.make_intent(a,jsonb_build_object('sourceRecord',b.artifact->'sourceRecord','parentResponse',b.artifact->'parentResponse','parentObjectReceipt',b.artifact->'parentObjectReceipt'),rid)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_BINDING' USING ERRCODE='42501';END IF;
 PERFORM design_normalization_processing.check_claim(a,c.intent);
 RETURN jsonb_build_object('schemaVersion','design-claimed-normalization-v1','artifact',b.artifact,'processingProvenance',jsonb_build_object('schemaVersion','design-normalization-processing-provenance-v1','claimId',c.id,'permissionId',c.permission_id,'intentDigest',design_dependency_authority.digest(c.intent),'artifactDigest',ad));END$$;
CREATE FUNCTION design_normalization_processing.bind_artifact(token text,scope jsonb,i jsonb,n jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c design_normalization_processing.claims;b design_normalization_processing.artifact_bindings;ad text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_normalization_processing.resolve(token,scope);c:=design_normalization_processing.check_claim(a,i);ad:=design_managed_normalized.check_artifact(a,n);
 IF (i IS DISTINCT FROM design_normalization_processing.make_intent(a,jsonb_build_object('sourceRecord',n->'sourceRecord','parentResponse',n->'parentResponse','parentObjectReceipt',n->'parentObjectReceipt'),n->>'requestId')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_BINDING' USING ERRCODE='42501';END IF;
 SELECT * INTO b FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;IF FOUND THEN IF (b.artifact IS DISTINCT FROM n OR b.artifact_digest IS DISTINCT FROM ad) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_CONFLICT';END IF;ELSE INSERT INTO design_normalization_processing.artifact_bindings VALUES(c.id,ad,n);END IF;
 RETURN design_normalization_processing.check_bound(design_normalization_processing.resolve(token,scope),i->>'requestId');END$$;
CREATE FUNCTION design_normalization_processing.read_bound_artifact(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE out jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;out:=design_normalization_processing.check_bound(design_normalization_processing.resolve(token,scope),rid);IF (out IS DISTINCT FROM design_normalization_processing.check_bound(design_normalization_processing.resolve(token,scope),rid)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_BINDING';END IF;RETURN out;END$$;
CREATE FUNCTION design_normalization_processing.read_claim(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c design_normalization_processing.claims;ad text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_runtime' OR rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_normalization_processing.resolve(token,scope);SELECT * INTO c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=rid;
 IF NOT FOUND THEN IF (design_normalization_processing.resolve(token,scope) IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED';END IF;RETURN NULL;END IF;
 PERFORM design_normalization_processing.check_claim(a,c.intent);SELECT x.artifact_digest INTO ad FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;IF FOUND THEN PERFORM design_normalization_processing.check_bound(a,rid);END IF;PERFORM design_normalization_processing.check_claim(design_normalization_processing.resolve(token,scope),c.intent);
 RETURN jsonb_build_object('claimId',c.id,'permissionId',c.permission_id,'intentDigest',design_dependency_authority.digest(c.intent),'artifactDigest',ad);END$$;
CREATE FUNCTION design_normalization_processing.issue_processing(token text,scope jsonb,pid text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;k text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_processing_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_normalization_processing.resolve(token,scope);PERFORM design_normalization_processing.check_intent(a,i);k:=design_normalization_processing.owner_key(a);
 IF EXISTS(SELECT 1 FROM design_normalization_processing.claims x WHERE x.owner_key=k AND x.request_id=i->>'requestId') THEN RAISE EXCEPTION 'PROCESSING_ALREADY_CLAIMED';END IF;
 INSERT INTO design_normalization_processing.permissions VALUES(pid,k,i->>'requestId',a,i,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_normalization_processing.permission(design_normalization_processing.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_normalization_processing.issuer_guard(token text,scope jsonb,i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_processing_issuer') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM design_normalization_processing.permission(design_normalization_processing.resolve(token,scope),i);PERFORM design_normalization_processing.permission(design_normalization_processing.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_normalization_processing.revoke(pid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n int;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_processing_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));UPDATE design_normalization_processing.permissions p SET active=false WHERE p.id=pid AND p.active;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
CREATE FUNCTION design_normalization_processing.is_revoked(pid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_processing_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));RETURN NOT EXISTS(SELECT 1 FROM design_normalization_processing.permissions p WHERE p.id=pid AND p.active);END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p WHERE p.pronamespace='design_normalization_processing'::regnamespace LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_managed_image_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_normalization_runtime,design_normalization_processing_issuer',f.sig);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION design_normalization_processing.prepare(text,jsonb,text,text,text),design_normalization_processing.authorize(text,jsonb,jsonb),design_normalization_processing.claim(text,jsonb,jsonb),design_normalization_processing.guard(text,jsonb,jsonb),design_normalization_processing.bind_artifact(text,jsonb,jsonb,jsonb),design_normalization_processing.read_bound_artifact(text,jsonb,text),design_normalization_processing.read_claim(text,jsonb,text) TO design_normalization_runtime;
GRANT EXECUTE ON FUNCTION design_normalization_processing.issue_processing(text,jsonb,text,jsonb,bigint),design_normalization_processing.issuer_guard(text,jsonb,jsonb),design_normalization_processing.revoke(text),design_normalization_processing.is_revoked(text) TO design_normalization_processing_issuer;
REVOKE CREATE ON SCHEMA design_normalization_processing FROM design_managed_image_capability;
REVOKE ALL ON ALL TABLES IN SCHEMA design_normalization_processing FROM PUBLIC,anon,authenticated,design_normalization_runtime,design_normalization_processing_issuer;
